## 3️⃣ `app.js`

```js
/* ==== CONFIG ==== */
const CLIENT_ID = "YOUR_DISCORD_CLIENT_ID";
const REDIRECT_URI = `${location.origin}${location.pathname}`; // same page
const SCOPES = "identify guilds";

/* ==== UI HELPERS ==== */
const $ = (sel) => document.querySelector(sel);
const hide = (el) => el.classList.add('hidden');
const show = (el) => el.classList.remove('hidden');

/* ==== AUTH FLOW ==== */
function startOAuth() {
    const authUrl = new URL("https://discord.com/api/oauth2/authorize");
    authUrl.searchParams.set("client_id", CLIENT_ID);
    authUrl.searchParams.set("redirect_uri", REDIRECT_URI);
    authUrl.searchParams.set("response_type", "code");
    authUrl.searchParams.set("scope", SCOPES);
    location.href = authUrl.toString();
}

/* ==== TOKEN EXCHANGE ==== */
/* 
   Discord does NOT allow client‑side token exchange (CORS + secret exposure). 
   You need a tiny server endpoint (e.g., Cloudflare Worker, Express, or FastAPI) that:
   1️⃣ Receives the `code` query param.
   2️⃣ POSTs it to https://discord.com/api/oauth2/token with your client_secret.
   3️⃣ Returns the access_token (and refresh token) as JSON.
   For demo purposes we’ll assume an endpoint at `/auth/token?code=...`.
*/
async function fetchAccessToken(code) {
    const resp = await fetch(`/auth/token?code=${code}`);
    if (!resp.ok) throw new Error("Token request failed");
    const data = await resp.json();
    return data.access_token;
}

/* ==== DASHBOARD DATA ==== */
async function loadDashboard(token) {
    // Bot status – replace with your own API
    const statusResp = await fetch("/api/bot/status", {
        headers: { Authorization: `Bearer ${token}` },
    });
    const { status } = await statusResp.json();
    $("#botStatus").textContent = status || "unknown";

    // Guild list – Discord endpoint (requires bot token with guilds scope)
    const guildResp = await fetch("https://discord.com/api/users/@me/guilds", {
        headers: { Authorization: `Bearer ${token}` },
    });
    const guilds = await guildResp.json();
    const guildList = $("#guildList");
    guildList.innerHTML = guilds
        .map(g => `<li>${g.name} (${g.id})</li>`)
        .join("");

    // Commands – your custom endpoint
    const cmdResp = await fetch("/api/bot/commands", {
        headers: { Authorization: `Bearer ${token}` },
    });
    const cmds = await cmdResp.json();
    const cmdList = $("#commandList");
    cmdList.innerHTML = cmds
        .map(c => `<li>/ ${c.name} – ${c.description}</li>`)
        .join("");
}

/* ==== INITIALISATION ==== */
window.addEventListener("DOMContentLoaded", async () => {
    // Buttons
    $("#loginBtn").addEventListener("click", startOAuth);
    $("#logoutBtn").addEventListener("click", () => location.reload());

    const params = new URLSearchParams(location.search);
    const code = params.get("code");

    if (code) {
        try {
            const token = await fetchAccessToken(code);
            hide($("#loginBtn"));
            show($("#logoutBtn"));
            show($("#dashboard"));
            await loadDashboard(token);
        } catch (e) {
            alert("Auth failed: " + e.message);
        }
    }
});
```

